node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const discountAmount = 20;
const newTotal = 102 - discountAmount;
const promoCodesJson = JSON.stringify(['SAVE20OFF']);

db.prepare(\"UPDATE carts SET discount_amount = ?, total = ?, applied_promo_codes_json = ? WHERE cart_id = ?\")
  .run(discountAmount, newTotal, promoCodesJson, 'CART-user_03dd1ad7');

// Verify the update
const cart = db.prepare(\"SELECT * FROM carts WHERE cart_id = ?\").get('CART-user_03dd1ad7');
console.log('Updated cart:', JSON.stringify(cart, null, 2));
"
